"use client";

import { useEffect, useState } from "react";
import { apiGet } from "@/lib/api-client";
import { useAppStore } from "@/store/app-store";
import { PageHeader } from "@/components/app/page-header";
import { StatusBadge } from "@/components/app/status-badge";
import { LoadingState, ErrorState, EmptyState } from "@/components/app/empty-state";
import { Card, CardContent } from "@/components/ui/card";
import { PackageCheck, Truck, Plane, Container } from "lucide-react";

const ASSET_ICONS: Record<string, any> = { TRUCK: Truck, AIR_CONTAINER: Container, FLIGHT_SLOT: Plane };

export function FleetView() {
  const [assets, setAssets] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    (async () => {
      try { const d = await apiGet("/assets"); setAssets(d.assets); }
      catch (e: any) { setError(e.message); }
      finally { setLoading(false); }
    })();
  }, []);

  if (loading) return <LoadingState />;
  if (error) return <ErrorState message={error} />;

  return (
    <div className="space-y-6">
      <PageHeader title="Đội xe & Phương tiện" description="Danh sách phương tiện vận chuyển chuyên dụng" icon={<PackageCheck className="h-5 w-5" />} />
      {assets.length === 0 ? <EmptyState icon={<PackageCheck className="h-6 w-6" />} title="Chưa có phương tiện" /> : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {assets.map((a) => {
            const Icon = ASSET_ICONS[a.type] || Truck;
            let configs: string[] = [];
            try { configs = JSON.parse(a.stallConfig || "{}").configs || []; } catch {}
            return (
              <Card key={a.assetId} className="transition-all hover:shadow-md">
                <CardContent className="p-5">
                  <div className="flex items-start justify-between">
                    <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-primary/10 text-primary"><Icon className="h-6 w-6" /></div>
                    <StatusBadge status={a.status} />
                  </div>
                  <h3 className="mt-3 text-base font-bold tracking-tight">{a.name}</h3>
                  <p className="text-xs text-muted-foreground">{a.type.replace(/_/g, " ")}</p>
                  <div className="mt-4 space-y-2 border-t border-border pt-3 text-xs">
                    <div className="flex justify-between"><span className="text-muted-foreground">Sức chứa</span><span className="font-medium">{a.capacity} ngựa</span></div>
                    <div className="flex justify-between"><span className="text-muted-foreground">Đối tác</span><span className="font-medium">{a.ownerPartner?.name || "Nội bộ"}</span></div>
                  </div>
                  {configs.length > 0 && (
                    <div className="mt-3">
                      <p className="text-[10px] font-medium uppercase tracking-wider text-muted-foreground">Cấu hình chuồng</p>
                      <div className="mt-1.5 flex flex-wrap gap-1.5">
                        {configs.map((c) => <span key={c} className="rounded bg-muted px-2 py-0.5 text-[10px] font-medium">{c}</span>)}
                      </div>
                    </div>
                  )}
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
}
